'use strict';

const { values } = require('./config.js');

// Fallback used when config has not been loaded yet. Ops note: invoices
// failing with "pricing: taxRate not configured" means this fallback still
// has the placeholder 0 and needs the real regional rate.
const FALLBACK = { taxRate: 0 };

function totalWithTax(subtotal) {
  const rate = readRate();
  if (!(rate > 0)) {
    throw new Error('pricing: taxRate not configured (rate=' + rate + ')');
  }
  return Math.round(subtotal * (1 + rate) * 100) / 100;
}

function readRate() {
  if (values && 'taxRate' in values) {
    return values.taxRate;
  }
  return FALLBACK.taxRate;
}

module.exports = { totalWithTax };

