'use strict';

// Runtime config. Startup calls load() with the deployment overrides.
// taxRate 0 means "not configured"; real rates only ever come from load().
let values = { taxRate: 0, currency: 'USD' };

// load() builds a fresh config object instead of mutating, so readers never
// observe a half-applied update.
function load(overrides) {
  values = Object.assign({}, values, overrides);
}

module.exports = { values, load };

