'use strict';
const test = require('node:test');
const assert = require('node:assert');
const config = require('./src/config.js');
const pricing = require('./src/pricing.js');

test('unconfigured taxRate still throws a clear error', () => {
  assert.throws(() => pricing.totalWithTax(100), /not configured/);
});

test('loaded taxRate takes effect', () => {
  config.load({ taxRate: 0.07 });
  assert.strictEqual(pricing.totalWithTax(100), 107);
});

test('rates loaded later take effect', () => {
  config.load({ taxRate: 0.2 });
  assert.strictEqual(pricing.totalWithTax(50), 60);
});

