'use strict';

// Runtime config. Startup calls load() with the deployment overrides.
// taxRate 0 means "not configured"; real rates only ever come from load().
const values = { taxRate: 0, currency: 'USD' };

// load() applies overrides onto the shared values object so every module
// holding a reference sees the update.
function load(overrides) {
  Object.assign(values, overrides);
}

module.exports = { values, load };
